catalog_script_client.script:
function onSubmit() {
    g_form.hideFieldMsg('data_fim');
    g_form.hideFieldMsg('vender_dias');

    var dias = parseInt(g_form.getValue('dias_solicitados'), 10);
    if (isNaN(dias) || dias <= 0) {
        g_form.showFieldMsg('data_fim',
          'Informe um período válido antes de enviar.', 'error');
        return false;
    }

    var vender = String(g_form.getValue('vender_dias')).toLowerCase();
    var vendeu = (vender === 'yes' || vender === 'true');
    if (vendeu && dias !== 20) {
        g_form.showFieldMsg('vender_dias',
          'Para vender 10 dias, o período solicitado deve ter exatamente 20 dias.', 'error');
        return false;
    }

    var saldo = parseInt(g_form.getValue('saldo_disponivel'), 10);
    var total = dias + (vendeu ? 10 : 0);
    if (!isNaN(saldo) && total > saldo) {
        g_form.showFieldMsg('data_fim',
          'Saldo insuficiente: este pedido usa ' + total +
          ' dias e você tem ' + saldo + ' disponíveis.', 'error');
        return false;
    }

    return true;
}
